insert into public.programmes (external_key, institution_id, faculty_id, code, name, category, qualification_level, duration_text, delivery_mode, overview, review_status, raw_payload) values ('botho-university-lesotho-bachelor-of-commerce-in-accounting', (select id from public.institutions where name = 'Botho University Lesotho' limit 1), null, 'BCO-7BO-20', 'Bachelor of Commerce in Accounting', 'Business & Commerce', 'Degree', '4 years with attachment', null, 'Your future in accounting starts here. The Bachelor of Commerce in Accounting offers a practical, industry-focused pathway to a rewarding career in accounting and finance. You will build expertise in financial reporting, auditing, taxation, and management accounting. What makes this degree distinctive is its strong balance of theory and practice, including a compulsory semester-long internship that provides invaluable real-world experience. Graduates are prepared for a wide range of careers in public and private accounting, financial analysis, banking, and government. The programme also lays a solid foundation for professional certifications such as ACCA, CPA, and CIMA, opening doors to advanced career opportunities and ensuring you are ready to excel in today''s financial world.', 'approved', '{"career_options": ["Accountant", "Auditor", "Financial Analyst", "Banking Officer"], "category": "Business & Commerce", "code": "BCO-7BO-20", "duration": "4 years with attachment", "extraction_method": "javascript_programme_objects", "faculty": null, "id": "botho-university-lesotho-bachelor-of-commerce-in-accounting", "institution": "Botho University Lesotho", "level": "Degree", "name": "Bachelor of Commerce in Accounting", "overview": "Your future in accounting starts here. The Bachelor of Commerce in Accounting offers a practical, industry-focused pathway to a rewarding career in accounting and finance. You will build expertise in financial reporting, auditing, taxation, and management accounting. What makes this degree distinctive is its strong balance of theory and practice, including a compulsory semester-long internship that provides invaluable real-world experience. Graduates are prepared for a wide range of careers in public and private accounting, financial analysis, banking, and government. The programme also lays a solid foundation for professional certifications such as ACCA, CPA, and CIMA, opening doors to advanced career opportunities and ensuring you are ready to excel in today''s financial world.", "requirements_summary": "IGCSE/BGCSE/equivalent with 5 Passes including English and Mathematics. Applicants in possession of a Diploma or Higher Diploma in related fields may be given exemptions based on the credit point equivalency.", "review_status": "approved", "skill_options": ["Financial reporting", "Auditing", "Taxation", "Bookkeeping"], "source_asset_url": "https://www.bothouniversity.com/assets/index-El4102Sb.js", "source_note": "Auto-enriched from repository evidence and institution rules.", "source_type": "official_js_bundle", "source_url": "https://www.bothouniversity.com/lesotho/programmes", "total_credits": 480, "total_modules": "38 (37 Core and 1 Elective)"}'::jsonb) on conflict (external_key) do update set institution_id = excluded.institution_id, faculty_id = excluded.faculty_id, code = excluded.code, name = excluded.name, category = excluded.category, qualification_level = excluded.qualification_level, duration_text = excluded.duration_text, delivery_mode = excluded.delivery_mode, overview = excluded.overview, review_status = excluded.review_status, raw_payload = excluded.raw_payload;
