insert into public.programmes (external_key, institution_id, faculty_id, code, name, category, qualification_level, duration_text, delivery_mode, overview, review_status, raw_payload) values ('national-university-of-lesotho-bachelor-of-urban-and-regional-planning-burp-8-semesters-4-years', (select id from public.institutions where name = 'National University of Lesotho' limit 1), (select f.id from public.faculties f join public.institutions i on i.id = f.institution_id where i.name = 'National University of Lesotho' and f.name = 'Science & Technology' limit 1), null, 'Bachelor Of Urban And Regional Planning (Burp) - 8 Semesters (4 Years)', 'Science & Technology', 'Degree', '4 years with project', null, null, 'approved', '{"career_options": ["Laboratory Technologist", "Research Scientist", "Science Teacher", "Quality Control Analyst"], "category": "Science & Technology", "duration": "4 years with project", "extraction_method": "html_headings_and_context", "faculty": "Science & Technology", "fee_note": "Fee schedule available: NUL Fee Structure 2024/25 (2024/25). Confirm the programme group and latest amount before payment.", "id": "national-university-of-lesotho-bachelor-of-urban-and-regional-planning-burp-8-semesters-4-years", "institution": "National University of Lesotho", "level": "Degree", "name": "Bachelor Of Urban And Regional Planning (Burp) - 8 Semesters (4 Years)", "requirements_summary": "For entry into the BURP degree, students must have: Sat for a minimum of six (6) subjects in LGCSE examinations or its equivalent. Obtained a C grade or better in Mathematics (candidates with a D grade will be required to enrol for, and successfully complete Mathematics Bridging Programme). Obtained a C grade or better in English Language (candidates with a D grade will be required to enrol for, and successfully complete English Language Bridging Programme). Obtained a C grade or better in other two subjects. Obtained a D grade or better in the remaining two subjects. Ranking: For purposes of admissions, students will be ranked according to the Admission Point Score (APS), using the points scored in the following subjects: Mathematics English Language Second Science subject or English Language (whichever is better)", "review_status": "approved", "skill_options": ["Laboratory practice", "Scientific method", "Data analysis", "Research methods"], "source_note": "Auto-enriched from repository evidence and institution rules.", "source_type": "official_academic_programmes_page", "source_url": "https://nul.ls/faculty-of-science-and-technology/academic-programmes/", "supporting_fee_source_path": "data/real/fees/nul-fee-structure-2024-2025.json"}'::jsonb) on conflict (external_key) do update set institution_id = excluded.institution_id, faculty_id = excluded.faculty_id, code = excluded.code, name = excluded.name, category = excluded.category, qualification_level = excluded.qualification_level, duration_text = excluded.duration_text, delivery_mode = excluded.delivery_mode, overview = excluded.overview, review_status = excluded.review_status, raw_payload = excluded.raw_payload;
insert into public.programme_sources (programme_id, source_document_id, relation_type, extraction_method, evidence_text) values ((select id from public.programmes where external_key = 'national-university-of-lesotho-bachelor-of-urban-and-regional-planning-burp-8-semesters-4-years' limit 1), (select id from public.source_documents where url = 'https://nul.ls/faculty-of-science-and-technology/academic-programmes/' limit 1), 'primary', 'html_headings_and_context', 'For entry into the BURP degree, students must have: Sat for a minimum of six (6) subjects in LGCSE examinations or its equivalent. Obtained a C grade or better in Mathematics (candidates with a D grade will be required to enrol for, and successfully complete Mathematics Bridging Programme). Obtained a C grade or better in English Language (candidates with a D grade will be required to enrol for, and successfully complete English Language Bridging Programme). Obtained a C grade or better in other two subjects. Obtained a D grade or better in the remaining two subjects. Ranking: For purposes of admissions, students will be ranked according to the Admission Point Score (APS), using the points scored in the following subjects: Mathematics English Language Second Science subject or English Language (whichever is better)') on conflict (programme_id, source_document_id, relation_type) do update set extraction_method = excluded.extraction_method, evidence_text = excluded.evidence_text;
