insert into public.programmes (external_key, institution_id, faculty_id, code, name, category, qualification_level, duration_text, delivery_mode, overview, review_status, raw_payload) values ('national-university-of-lesotho-bachelor-of-arts-in-library-and-information-studies', (select id from public.institutions where name = 'National University of Lesotho' limit 1), (select f.id from public.faculties f join public.institutions i on i.id = f.institution_id where i.name = 'National University of Lesotho' and f.name = 'Humanities' limit 1), null, 'Bachelor Of Arts In Library And Information Studies', 'Humanities', 'Degree', '4 years with project', null, null, 'approved', '{"career_options": ["Programme Specialist", "Project Officer", "Research Assistant", "Community Development Officer"], "category": "Humanities", "duration": "4 years with project", "extraction_method": "html_headings_and_context", "faculty": "Humanities", "fee_note": "Fee schedule available: NUL Fee Structure 2024/25 (2024/25). Confirm the programme group and latest amount before payment.", "id": "national-university-of-lesotho-bachelor-of-arts-in-library-and-information-studies", "institution": "National University of Lesotho", "level": "Degree", "name": "Bachelor Of Arts In Library And Information Studies", "requirements_summary": "The normal entry requirements for candidates shall be: Diploma in Library and Information Studies or equivalent. Such candidates when admitted will start their programme at the second year level of this programme. Duration for Direct Entry - 4 years Candidates who apply for admission into the Bachelor of Library and Information Studies programme must satisfy the General Regulations into the BA degree of the Faculty of Humanities. For admissibility into Year 1, applicants must have: Sat for a minimum of Six (6) subjects of the Lesotho General Certificate (LGCSE) examinations. Obtained C grade or better, in (4) subjects including English Language. Obtained a D in the remaining two (2) subjects chosen from designed five subject groups and a minimum Admission Point Score (APS) that shall not exceed 26.", "review_status": "approved", "skill_options": ["Communication", "Research methods", "Problem solving", "Professional practice"], "source_note": "Auto-enriched from repository evidence and institution rules.", "source_type": "official_academic_programmes_page", "source_url": "https://nul.ls/humanities/academic-programmes/", "supporting_fee_source_path": "data/real/fees/nul-fee-structure-2024-2025.json"}'::jsonb) on conflict (external_key) do update set institution_id = excluded.institution_id, faculty_id = excluded.faculty_id, code = excluded.code, name = excluded.name, category = excluded.category, qualification_level = excluded.qualification_level, duration_text = excluded.duration_text, delivery_mode = excluded.delivery_mode, overview = excluded.overview, review_status = excluded.review_status, raw_payload = excluded.raw_payload;
insert into public.programme_sources (programme_id, source_document_id, relation_type, extraction_method, evidence_text) values ((select id from public.programmes where external_key = 'national-university-of-lesotho-bachelor-of-arts-in-library-and-information-studies' limit 1), (select id from public.source_documents where url = 'https://nul.ls/humanities/academic-programmes/' limit 1), 'primary', 'html_headings_and_context', 'The normal entry requirements for candidates shall be: Diploma in Library and Information Studies or equivalent. Such candidates when admitted will start their programme at the second year level of this programme. Duration for Direct Entry - 4 years Candidates who apply for admission into the Bachelor of Library and Information Studies programme must satisfy the General Regulations into the BA degree of the Faculty of Humanities. For admissibility into Year 1, applicants must have: Sat for a minimum of Six (6) subjects of the Lesotho General Certificate (LGCSE) examinations. Obtained C grade or better, in (4) subjects including English Language. Obtained a D in the remaining two (2) subjects chosen from designed five subject groups and a minimum Admission Point Score (APS) that shall not exceed 26.') on conflict (programme_id, source_document_id, relation_type) do update set extraction_method = excluded.extraction_method, evidence_text = excluded.evidence_text;
