insert into public.programmes (external_key, institution_id, faculty_id, code, name, category, qualification_level, duration_text, delivery_mode, overview, review_status, raw_payload) values ('national-university-of-lesotho-certificate-of-proficiency-in-insurance-law', (select id from public.institutions where name = 'National University of Lesotho' limit 1), (select f.id from public.faculties f join public.institutions i on i.id = f.institution_id where i.name = 'National University of Lesotho' and f.name = 'Law' limit 1), null, 'Certificate Of Proficiency In Insurance Law', 'Law', 'Certificate', '2 years', null, null, 'approved', '{"career_options": ["Legal Advisor", "Legal Officer", "Compliance Officer", "Human Rights Officer"], "category": "Law", "duration": "2 years", "extraction_method": "html_headings_and_context", "faculty": "Law", "fee_note": "Fee schedule available: NUL Fee Structure 2024/25 (2024/25). Confirm the programme group and latest amount before payment.", "id": "national-university-of-lesotho-certificate-of-proficiency-in-insurance-law", "institution": "National University of Lesotho", "level": "Certificate", "name": "Certificate Of Proficiency In Insurance Law", "requirements_summary": "The programme is a Certificate in Insurance Law at Level 5 of the Lesotho Qualification Framework (LQF) and Level 5 of SADC Qualifications Framework (SADCQF). The minimum entry requirements into the certificate programme will be based on one of the following: A Cambridge Overseas Schools Certificate (COSC), Lesotho General Certificate of Secondary Education (LGCSE), or equivalent certificate; or Recognition of prior learning. Mode of Learning The courses will combine theory and practice in the form of case studies. Students are expected to read on their own. Lectures are conducted in a structured but discursive manner allowing for questions and discussions. Practical examples are routinely considered with reference to case law, experience from the industry and other available resources. Course Rationale The COP is a qualification developed as part of the fit and proper requirements for insurance intermediaries in Lesotho. The programme aims to provide students with introductory knowledge on key aspects of the insurance sector such as the legal framework governing Lesotho''s insurance sector, the role of the Regulator in the insurance sector, ethical considerations in the insurance business among other things. The programme will also equip students with cognitive and conceptual tools such as problem solving skills, application skills, and to some extent analytical skills which will enable students to deal with risk and compliance management, ethical considerations, and dispute resolution in the insurance business. It will introduce students to the fundamental aspects of the regulation of insurance business in Lesotho by emphasizing selected general principles in insurance and related areas together with more specific areas, such as insurance products, risk management and others. The programme is designed to equip students with the relevant knowledge and practical skills required to successfully operate within the insurance environment in Lesotho.", "review_status": "approved", "skill_options": ["Legal research", "Case analysis", "Legal writing", "Advocacy"], "source_note": "Auto-enriched from repository evidence and institution rules.", "source_type": "official_academic_programmes_page", "source_url": "https://nul.ls/faculty-of-law/academic-programmes/", "supporting_fee_source_path": "data/real/fees/nul-fee-structure-2024-2025.json"}'::jsonb) on conflict (external_key) do update set institution_id = excluded.institution_id, faculty_id = excluded.faculty_id, code = excluded.code, name = excluded.name, category = excluded.category, qualification_level = excluded.qualification_level, duration_text = excluded.duration_text, delivery_mode = excluded.delivery_mode, overview = excluded.overview, review_status = excluded.review_status, raw_payload = excluded.raw_payload;
insert into public.programme_sources (programme_id, source_document_id, relation_type, extraction_method, evidence_text) values ((select id from public.programmes where external_key = 'national-university-of-lesotho-certificate-of-proficiency-in-insurance-law' limit 1), (select id from public.source_documents where url = 'https://nul.ls/faculty-of-law/academic-programmes/' limit 1), 'primary', 'html_headings_and_context', 'The programme is a Certificate in Insurance Law at Level 5 of the Lesotho Qualification Framework (LQF) and Level 5 of SADC Qualifications Framework (SADCQF). The minimum entry requirements into the certificate programme will be based on one of the following: A Cambridge Overseas Schools Certificate (COSC), Lesotho General Certificate of Secondary Education (LGCSE), or equivalent certificate; or Recognition of prior learning. Mode of Learning The courses will combine theory and practice in the form of case studies. Students are expected to read on their own. Lectures are conducted in a structured but discursive manner allowing for questions and discussions. Practical examples are routinely considered with reference to case law, experience from the industry and other available resources. Course Rationale The COP is a qualification developed as part of the fit and proper requirements for insurance intermediaries in Lesotho. The programme aims to provide students with introductory knowledge on key aspects of the insurance sector such as the legal framework governing Lesotho''s insurance sector, the role of the Regulator in the insurance sector, ethical considerations in the insurance business among other things. The programme will also equip students with cognitive and conceptual tools such as problem solving skills, application skills, and to some extent analytical skills which will enable students to deal with risk and compliance management, ethical considerations, and dispute resolution in the insurance business. It will introduce students to the fundamental aspects of the regulation of insurance business in Lesotho by emphasizing selected general principles in insurance and related areas together with more specific areas, such as insurance products, risk management and others. The programme is designed to equip students with the relevant knowledge and practical skills required to successfully operate within the insurance environment in Lesotho.') on conflict (programme_id, source_document_id, relation_type) do update set extraction_method = excluded.extraction_method, evidence_text = excluded.evidence_text;
insert into public.programme_sources (programme_id, source_document_id, relation_type, extraction_method) values ((select id from public.programmes where external_key = 'national-university-of-lesotho-certificate-of-proficiency-in-insurance-law' limit 1), (select id from public.source_documents where local_path = 'data/real/fees/nul-fee-structure-2024-2025.json' limit 1), 'fee_supporting', 'html_headings_and_context') on conflict (programme_id, source_document_id, relation_type) do update set extraction_method = excluded.extraction_method;
insert into public.programme_requirement_sets (programme_id, route_name, requirement_summary, source_document_id, review_status, raw_payload) values ((select id from public.programmes where external_key = 'national-university-of-lesotho-certificate-of-proficiency-in-insurance-law' limit 1), 'General entry', 'The programme is a Certificate in Insurance Law at Level 5 of the Lesotho Qualification Framework (LQF) and Level 5 of SADC Qualifications Framework (SADCQF). The minimum entry requirements into the certificate programme will be based on one of the following: A Cambridge Overseas Schools Certificate (COSC), Lesotho General Certificate of Secondary Education (LGCSE), or equivalent certificate; or Recognition of prior learning. Mode of Learning The courses will combine theory and practice in the form of case studies. Students are expected to read on their own. Lectures are conducted in a structured but discursive manner allowing for questions and discussions. Practical examples are routinely considered with reference to case law, experience from the industry and other available resources. Course Rationale The COP is a qualification developed as part of the fit and proper requirements for insurance intermediaries in Lesotho. The programme aims to provide students with introductory knowledge on key aspects of the insurance sector such as the legal framework governing Lesotho''s insurance sector, the role of the Regulator in the insurance sector, ethical considerations in the insurance business among other things. The programme will also equip students with cognitive and conceptual tools such as problem solving skills, application skills, and to some extent analytical skills which will enable students to deal with risk and compliance management, ethical considerations, and dispute resolution in the insurance business. It will introduce students to the fundamental aspects of the regulation of insurance business in Lesotho by emphasizing selected general principles in insurance and related areas together with more specific areas, such as insurance products, risk management and others. The programme is designed to equip students with the relevant knowledge and practical skills required to successfully operate within the insurance environment in Lesotho.', (select id from public.source_documents where url = 'https://nul.ls/faculty-of-law/academic-programmes/' limit 1), 'approved', '{"source_field": "requirements_summary"}'::jsonb) on conflict (programme_id, route_name) do update set requirement_summary = excluded.requirement_summary, source_document_id = excluded.source_document_id, review_status = excluded.review_status, raw_payload = excluded.raw_payload;
