insert into public.programmes (external_key, institution_id, faculty_id, code, name, category, qualification_level, duration_text, delivery_mode, overview, review_status, raw_payload) values ('national-university-of-lesotho-bachelor-of-laws-ll-b', (select id from public.institutions where name = 'National University of Lesotho' limit 1), (select f.id from public.faculties f join public.institutions i on i.id = f.institution_id where i.name = 'National University of Lesotho' and f.name = 'Law' limit 1), null, 'Bachelor Of Laws (LL.B.)', 'Law', 'Degree', '5 years with attachment and project', null, null, 'approved', '{"career_options": ["Legal Advisor", "Legal Officer", "Compliance Officer", "Human Rights Officer"], "category": "Law", "duration": "5 years with attachment and project", "extraction_method": "html_headings_and_context", "faculty": "Law", "fee_note": "Fee schedule available: NUL Fee Structure 2024/25 (2024/25). Confirm the programme group and latest amount before payment.", "id": "national-university-of-lesotho-bachelor-of-laws-ll-b", "institution": "National University of Lesotho", "level": "Degree", "name": "Bachelor Of Laws (LL.B.)", "requirements_summary": "Mode 1 - LL.B. 5-year programme The normal requirements for entry into the LL.B. 5-year programme are: Sat for a minimum of six (6) subjects in LGCSE or COSC examination LGCSE or equivalent with at least four subjects passed with a C-grade and two other subjects passed with at least a D- grade. A minimum of a C-grade in English Language. A total not exceeding 26 Average Point Score (APS) is the acceptable achievement of a candidate. Mode 2 - LL.B. 3-year Programme The normal requirements for applicants shall be: A Bachelors'' Degree from any other discipline with at least a Second Class Second-Division Pass (i.e. at least a 60 percent average or equivalent). Mode 3 - LL.B. 2-year Programme", "review_status": "approved", "skill_options": ["Legal research", "Case analysis", "Legal writing", "Advocacy"], "source_note": "Auto-enriched from repository evidence and institution rules.", "source_type": "official_academic_programmes_page", "source_url": "https://nul.ls/faculty-of-law/academic-programmes/", "supporting_fee_source_path": "data/real/fees/nul-fee-structure-2024-2025.json"}'::jsonb) on conflict (external_key) do update set institution_id = excluded.institution_id, faculty_id = excluded.faculty_id, code = excluded.code, name = excluded.name, category = excluded.category, qualification_level = excluded.qualification_level, duration_text = excluded.duration_text, delivery_mode = excluded.delivery_mode, overview = excluded.overview, review_status = excluded.review_status, raw_payload = excluded.raw_payload;
insert into public.programme_sources (programme_id, source_document_id, relation_type, extraction_method, evidence_text) values ((select id from public.programmes where external_key = 'national-university-of-lesotho-bachelor-of-laws-ll-b' limit 1), (select id from public.source_documents where url = 'https://nul.ls/faculty-of-law/academic-programmes/' limit 1), 'primary', 'html_headings_and_context', 'Mode 1 - LL.B. 5-year programme The normal requirements for entry into the LL.B. 5-year programme are: Sat for a minimum of six (6) subjects in LGCSE or COSC examination LGCSE or equivalent with at least four subjects passed with a C-grade and two other subjects passed with at least a D- grade. A minimum of a C-grade in English Language. A total not exceeding 26 Average Point Score (APS) is the acceptable achievement of a candidate. Mode 2 - LL.B. 3-year Programme The normal requirements for applicants shall be: A Bachelors'' Degree from any other discipline with at least a Second Class Second-Division Pass (i.e. at least a 60 percent average or equivalent). Mode 3 - LL.B. 2-year Programme') on conflict (programme_id, source_document_id, relation_type) do update set extraction_method = excluded.extraction_method, evidence_text = excluded.evidence_text;
