insert into public.programmes (external_key, institution_id, faculty_id, code, name, category, qualification_level, duration_text, delivery_mode, overview, review_status, raw_payload) values ('national-university-of-lesotho-postgraduate-diploma-in-pension-law', (select id from public.institutions where name = 'National University of Lesotho' limit 1), (select f.id from public.faculties f join public.institutions i on i.id = f.institution_id where i.name = 'National University of Lesotho' and f.name = 'Law' limit 1), null, 'Postgraduate Diploma In Pension Law', 'Law', 'Diploma', '3 years', null, null, 'approved', '{"career_options": ["Legal Advisor", "Legal Officer", "Compliance Officer", "Human Rights Officer"], "category": "Law", "duration": "3 years", "extraction_method": "html_headings_and_context", "faculty": "Law", "fee_note": "Fee schedule available: NUL Fee Structure 2024/25 (2024/25). Confirm the programme group and latest amount before payment.", "id": "national-university-of-lesotho-postgraduate-diploma-in-pension-law", "institution": "National University of Lesotho", "level": "Diploma", "name": "Postgraduate Diploma In Pension Law", "requirements_summary": "A recognised Bachelor''s Degree with a minimum of Second Class-Second Division Or A recognised Bachelor''s Degree with Pass, coupled with extensive work experience. The Executive Professional Development Programme This is an executive professional development programme targeting the busy professionals who wish to gain specialized knowledge in pension law. The programme is comprehensive and practical, ideal for decision makers and advisors of the pension fund business. The program comprises of ten intricate courses, namely, Introduction to Lesotho''s Private Pension Fund System, Pension Funds and the Employment Connection, Death Benefits Before Retirement, Deductions from Pension Benefits, Disability Benefits, Member''s Right to Information, Financial Planning and Pension Funds, Governance of Pension Funds, Investment Regulation, The Role of and Functions of the Regulator. The following are some of the topics covered in the programme: The regulatory and legislative framework of the pension fund business in Lesotho Pensions and the employment relationship Pension plan funding requirements and investment principles", "review_status": "approved", "skill_options": ["Legal research", "Case analysis", "Legal writing", "Advocacy"], "source_note": "Auto-enriched from repository evidence and institution rules.", "source_type": "official_academic_programmes_page", "source_url": "https://nul.ls/faculty-of-law/academic-programmes/", "supporting_fee_source_path": "data/real/fees/nul-fee-structure-2024-2025.json"}'::jsonb) on conflict (external_key) do update set institution_id = excluded.institution_id, faculty_id = excluded.faculty_id, code = excluded.code, name = excluded.name, category = excluded.category, qualification_level = excluded.qualification_level, duration_text = excluded.duration_text, delivery_mode = excluded.delivery_mode, overview = excluded.overview, review_status = excluded.review_status, raw_payload = excluded.raw_payload;
insert into public.programme_sources (programme_id, source_document_id, relation_type, extraction_method, evidence_text) values ((select id from public.programmes where external_key = 'national-university-of-lesotho-postgraduate-diploma-in-pension-law' limit 1), (select id from public.source_documents where url = 'https://nul.ls/faculty-of-law/academic-programmes/' limit 1), 'primary', 'html_headings_and_context', 'A recognised Bachelor''s Degree with a minimum of Second Class-Second Division Or A recognised Bachelor''s Degree with Pass, coupled with extensive work experience. The Executive Professional Development Programme This is an executive professional development programme targeting the busy professionals who wish to gain specialized knowledge in pension law. The programme is comprehensive and practical, ideal for decision makers and advisors of the pension fund business. The program comprises of ten intricate courses, namely, Introduction to Lesotho''s Private Pension Fund System, Pension Funds and the Employment Connection, Death Benefits Before Retirement, Deductions from Pension Benefits, Disability Benefits, Member''s Right to Information, Financial Planning and Pension Funds, Governance of Pension Funds, Investment Regulation, The Role of and Functions of the Regulator. The following are some of the topics covered in the programme: The regulatory and legislative framework of the pension fund business in Lesotho Pensions and the employment relationship Pension plan funding requirements and investment principles') on conflict (programme_id, source_document_id, relation_type) do update set extraction_method = excluded.extraction_method, evidence_text = excluded.evidence_text;
insert into public.programme_sources (programme_id, source_document_id, relation_type, extraction_method) values ((select id from public.programmes where external_key = 'national-university-of-lesotho-postgraduate-diploma-in-pension-law' limit 1), (select id from public.source_documents where local_path = 'data/real/fees/nul-fee-structure-2024-2025.json' limit 1), 'fee_supporting', 'html_headings_and_context') on conflict (programme_id, source_document_id, relation_type) do update set extraction_method = excluded.extraction_method;
insert into public.programme_requirement_sets (programme_id, route_name, requirement_summary, source_document_id, review_status, raw_payload) values ((select id from public.programmes where external_key = 'national-university-of-lesotho-postgraduate-diploma-in-pension-law' limit 1), 'General entry', 'A recognised Bachelor''s Degree with a minimum of Second Class-Second Division Or A recognised Bachelor''s Degree with Pass, coupled with extensive work experience. The Executive Professional Development Programme This is an executive professional development programme targeting the busy professionals who wish to gain specialized knowledge in pension law. The programme is comprehensive and practical, ideal for decision makers and advisors of the pension fund business. The program comprises of ten intricate courses, namely, Introduction to Lesotho''s Private Pension Fund System, Pension Funds and the Employment Connection, Death Benefits Before Retirement, Deductions from Pension Benefits, Disability Benefits, Member''s Right to Information, Financial Planning and Pension Funds, Governance of Pension Funds, Investment Regulation, The Role of and Functions of the Regulator. The following are some of the topics covered in the programme: The regulatory and legislative framework of the pension fund business in Lesotho Pensions and the employment relationship Pension plan funding requirements and investment principles', (select id from public.source_documents where url = 'https://nul.ls/faculty-of-law/academic-programmes/' limit 1), 'approved', '{"source_field": "requirements_summary"}'::jsonb) on conflict (programme_id, route_name) do update set requirement_summary = excluded.requirement_summary, source_document_id = excluded.source_document_id, review_status = excluded.review_status, raw_payload = excluded.raw_payload;
