insert into public.programmes (external_key, institution_id, faculty_id, code, name, category, qualification_level, duration_text, delivery_mode, overview, review_status, raw_payload) values ('national-university-of-lesotho-master-of-laws', (select id from public.institutions where name = 'National University of Lesotho' limit 1), (select f.id from public.faculties f join public.institutions i on i.id = f.institution_id where i.name = 'National University of Lesotho' and f.name = 'Law' limit 1), null, 'Master Of Laws', 'Law', 'Masters', '3 years', null, null, 'approved', '{"career_options": ["Legal Advisor", "Legal Officer", "Compliance Officer", "Human Rights Officer"], "category": "Law", "duration": "3 years", "extraction_method": "html_headings_and_context", "faculty": "Law", "fee_note": "Fee schedule available: NUL Fee Structure 2024/25 (2024/25). Confirm the programme group and latest amount before payment.", "id": "national-university-of-lesotho-master-of-laws", "institution": "National University of Lesotho", "level": "Masters", "name": "Master Of Laws", "requirements_summary": "Modes of the Degree The Faculty of Law offers the degree of Master of Laws (LL.M) in three modes, viz.: the structured general, unspecialised mode; the structured specialised LL.M degree mode; and the full dissertation mode. The Structured General LL.M Mode The Structured General LL.M degree allows a candidate to determine the content of their degree through their course selection. A candidate registered in the Structured General LL.M degree programme may select any courses from the list of the courses that are on offer across specialisation areas. During the first semester candidates shall", "review_status": "approved", "skill_options": ["Legal research", "Case analysis", "Legal writing", "Advocacy"], "source_note": "Auto-enriched from repository evidence and institution rules.", "source_type": "official_academic_programmes_page", "source_url": "https://nul.ls/faculty-of-law/academic-programmes/", "supporting_fee_source_path": "data/real/fees/nul-fee-structure-2024-2025.json"}'::jsonb) on conflict (external_key) do update set institution_id = excluded.institution_id, faculty_id = excluded.faculty_id, code = excluded.code, name = excluded.name, category = excluded.category, qualification_level = excluded.qualification_level, duration_text = excluded.duration_text, delivery_mode = excluded.delivery_mode, overview = excluded.overview, review_status = excluded.review_status, raw_payload = excluded.raw_payload;
insert into public.programme_sources (programme_id, source_document_id, relation_type, extraction_method, evidence_text) values ((select id from public.programmes where external_key = 'national-university-of-lesotho-master-of-laws' limit 1), (select id from public.source_documents where url = 'https://nul.ls/faculty-of-law/academic-programmes/' limit 1), 'primary', 'html_headings_and_context', 'Modes of the Degree The Faculty of Law offers the degree of Master of Laws (LL.M) in three modes, viz.: the structured general, unspecialised mode; the structured specialised LL.M degree mode; and the full dissertation mode. The Structured General LL.M Mode The Structured General LL.M degree allows a candidate to determine the content of their degree through their course selection. A candidate registered in the Structured General LL.M degree programme may select any courses from the list of the courses that are on offer across specialisation areas. During the first semester candidates shall') on conflict (programme_id, source_document_id, relation_type) do update set extraction_method = excluded.extraction_method, evidence_text = excluded.evidence_text;
