insert into public.programmes (external_key, institution_id, faculty_id, code, name, category, qualification_level, duration_text, delivery_mode, overview, review_status, raw_payload) values ('national-university-of-lesotho-bachelor-of-arts-public-administration-double-major', (select id from public.institutions where name = 'National University of Lesotho' limit 1), (select f.id from public.faculties f join public.institutions i on i.id = f.institution_id where i.name = 'National University of Lesotho' and f.name = 'Social Sciences' limit 1), null, 'Bachelor Of Arts Public Administration (Double Major)', 'Social Sciences', 'Degree', '4 years with project', null, null, 'approved', '{"career_options": ["Social Worker", "Community Development Officer", "Youth Programme Officer", "Social Researcher"], "category": "Social Sciences", "duration": "4 years with project", "extraction_method": "html_headings_and_context", "faculty": "Social Sciences", "fee_note": "Fee schedule available: NUL Fee Structure 2024/25 (2024/25). Confirm the programme group and latest amount before payment.", "id": "national-university-of-lesotho-bachelor-of-arts-public-administration-double-major", "institution": "National University of Lesotho", "level": "Degree", "name": "Bachelor Of Arts Public Administration (Double Major)", "requirements_summary": ": To be considered for admission, candidates must have: Sat for a minimum of six (6) subjects in LGCSE Examination LGCSE or its equivalent with a minimum achievement rating of a \"C\" or better in four subjects including English Language. A \"D\" or better in the remaining two subjects. Indirect Entry The normal entry requirements for candidates shall be: Diploma in Public Administration of Lesotho Institute of Public Administration and Management (LIPAM) with at least a Pass with Credit.", "review_status": "approved", "skill_options": ["Case management", "Community engagement", "Social research", "Counselling skills"], "source_note": "Auto-enriched from repository evidence and institution rules.", "source_type": "official_academic_programmes_page", "source_url": "https://nul.ls/faculty-of-social-sciences/academic-programmes/", "supporting_fee_source_path": "data/real/fees/nul-fee-structure-2024-2025.json"}'::jsonb) on conflict (external_key) do update set institution_id = excluded.institution_id, faculty_id = excluded.faculty_id, code = excluded.code, name = excluded.name, category = excluded.category, qualification_level = excluded.qualification_level, duration_text = excluded.duration_text, delivery_mode = excluded.delivery_mode, overview = excluded.overview, review_status = excluded.review_status, raw_payload = excluded.raw_payload;
insert into public.programme_sources (programme_id, source_document_id, relation_type, extraction_method, evidence_text) values ((select id from public.programmes where external_key = 'national-university-of-lesotho-bachelor-of-arts-public-administration-double-major' limit 1), (select id from public.source_documents where url = 'https://nul.ls/faculty-of-social-sciences/academic-programmes/' limit 1), 'primary', 'html_headings_and_context', ': To be considered for admission, candidates must have: Sat for a minimum of six (6) subjects in LGCSE Examination LGCSE or its equivalent with a minimum achievement rating of a "C" or better in four subjects including English Language. A "D" or better in the remaining two subjects. Indirect Entry The normal entry requirements for candidates shall be: Diploma in Public Administration of Lesotho Institute of Public Administration and Management (LIPAM) with at least a Pass with Credit.') on conflict (programme_id, source_document_id, relation_type) do update set extraction_method = excluded.extraction_method, evidence_text = excluded.evidence_text;
