insert into public.programmes (external_key, institution_id, faculty_id, code, name, category, qualification_level, duration_text, delivery_mode, overview, review_status, raw_payload) values ('centre-for-accounting-studies-certified-accounting-technician-certificate-cat', (select id from public.institutions where name = 'Centre for Accounting Studies' limit 1), (select f.id from public.faculties f join public.institutions i on i.id = f.institution_id where i.name = 'Centre for Accounting Studies' and f.name = 'Accounting and Financial Services' limit 1), null, 'Certified Accounting Technician Certificate (CAT)', 'Business & Commerce', 'Certificate', '3 years', null, 'The CAT qualification is offered on a 12 months basis from January to December and July to June. The CAT qualification level is the preparation stage for the ACCA qualification. Therefore, upon completion there is automatic transfer onto ACCA qualification programme and will be given free exemptions from the first three examinations at Applied Knowledge Skills Module level. That is; Completion of CAT Stage Certificate lead to Applied Skills Module level of the ACCA qualification. There are nine modules in this qualification.', 'approved', '{"career_options": ["Accountant", "Auditor", "Financial Analyst", "Banking Officer"], "category": "Business & Commerce", "duration": "3 years", "extraction_method": "html_course_page_plus_manual_handbook_extract", "faculty": "Accounting and Financial Services", "fee_note": "Fee schedule available: CAS fees partial manual extract (current evidence). Confirm the programme group and latest amount before payment.", "handbook_levels": ["CAT (entry)"], "id": "centre-for-accounting-studies-certified-accounting-technician-certificate-cat", "institution": "Centre for Accounting Studies", "level": "Certificate", "name": "Certified Accounting Technician Certificate (CAT)", "overview": "The CAT qualification is offered on a 12 months basis from January to December and July to June. The CAT qualification level is the preparation stage for the ACCA qualification. Therefore, upon completion there is automatic transfer onto ACCA qualification programme and will be given free exemptions from the first three examinations at Applied Knowledge Skills Module level. That is; Completion of CAT Stage Certificate lead to Applied Skills Module level of the ACCA qualification. There are nine modules in this qualification.", "requirements_summary": "LGCSE/COSC with minimum 6 subjects, 4 credits including Mathematics or English or Accounting, and aggregate not exceeding 36; or Diploma/IB/Certificate from a MOET-registered TVET institution; or comparable qualifications assessed by ECOL/MOET.", "review_status": "approved", "skill_options": ["Financial reporting", "Auditing", "Taxation", "Bookkeeping"], "source_note": "Auto-enriched from repository evidence and institution rules.", "source_type": "official_course_page", "source_url": "https://cas.ac.ls/course/certified-accounting-certificate-cat/", "supporting_fee_source_path": "data/real/fees/cas-fee-structure-partial-2024.json", "supporting_source_path": "C:/Users/lepha/Downloads/CAS Lesotho Student-Handbook-Volume-4.pdf"}'::jsonb) on conflict (external_key) do update set institution_id = excluded.institution_id, faculty_id = excluded.faculty_id, code = excluded.code, name = excluded.name, category = excluded.category, qualification_level = excluded.qualification_level, duration_text = excluded.duration_text, delivery_mode = excluded.delivery_mode, overview = excluded.overview, review_status = excluded.review_status, raw_payload = excluded.raw_payload;
insert into public.programme_sources (programme_id, source_document_id, relation_type, extraction_method, evidence_text) values ((select id from public.programmes where external_key = 'centre-for-accounting-studies-certified-accounting-technician-certificate-cat' limit 1), (select id from public.source_documents where url = 'https://cas.ac.ls/course/certified-accounting-certificate-cat/' limit 1), 'primary', 'html_course_page_plus_manual_handbook_extract', 'LGCSE/COSC with minimum 6 subjects, 4 credits including Mathematics or English or Accounting, and aggregate not exceeding 36; or Diploma/IB/Certificate from a MOET-registered TVET institution; or comparable qualifications assessed by ECOL/MOET.') on conflict (programme_id, source_document_id, relation_type) do update set extraction_method = excluded.extraction_method, evidence_text = excluded.evidence_text;
