insert into public.programmes (external_key, institution_id, faculty_id, code, name, category, qualification_level, duration_text, delivery_mode, overview, review_status, raw_payload) values ('centre-for-accounting-studies-association-of-chartered-certified-accountants-acca', (select id from public.institutions where name = 'Centre for Accounting Studies' limit 1), (select f.id from public.faculties f join public.institutions i on i.id = f.institution_id where i.name = 'Centre for Accounting Studies' and f.name = 'Accounting and Financial Services' limit 1), null, 'Association of Chartered Certified Accountants (ACCA)', 'Business & Commerce', 'Professional Qualification', '3 years', null, 'ACCA is the world''s most forward-thinking professional accountancy body. ACCA is able to create the innovative, strategic-thinking accountants for the fast-changing world. It is the largest professional body of financial accountants. ACCA qualification is recognized on a variety of national frameworks around the world and accredited by the Lesotho Council on Higher Education (CHE). ACCA has a joint examination partnership with the Lesotho Institute of Accountants that allows students to qualify using the ACCA qualification structure. This is the gold standard qualification in accountancy, opening doors to highly respected, interesting career opportunities in any sector.', 'approved', '{"career_options": ["Accountant", "Auditor", "Financial Analyst", "Banking Officer"], "category": "Business & Commerce", "duration": "3 years", "extraction_method": "html_course_page_plus_manual_handbook_extract", "faculty": "Accounting and Financial Services", "fee_note": "Fee schedule available: CAS fees partial manual extract (current evidence). Confirm the programme group and latest amount before payment.", "handbook_levels": ["CAT (entry)", "Applied Knowledge", "Applied Skills 1", "Applied Skills 2", "Strategic Professional"], "id": "centre-for-accounting-studies-association-of-chartered-certified-accountants-acca", "institution": "Centre for Accounting Studies", "level": "Professional Qualification", "name": "Association of Chartered Certified Accountants (ACCA)", "overview": "ACCA is the world''s most forward-thinking professional accountancy body. ACCA is able to create the innovative, strategic-thinking accountants for the fast-changing world. It is the largest professional body of financial accountants. ACCA qualification is recognized on a variety of national frameworks around the world and accredited by the Lesotho Council on Higher Education (CHE). ACCA has a joint examination partnership with the Lesotho Institute of Accountants that allows students to qualify using the ACCA qualification structure. This is the gold standard qualification in accountancy, opening doors to highly respected, interesting career opportunities in any sector.", "requirements_summary": "CAT entry requires LGCSE/COSC with minimum 6 subjects, 4 credits including Mathematics or English or Accounting, and aggregate not exceeding 36. Applied Knowledge entry is available to non-accounting degree holders, diploma holders from HEI/TVET, or A-Level applicants with Mathematics and English plus 3 years accounting work experience.", "review_status": "approved", "skill_options": ["Financial reporting", "Auditing", "Taxation", "Bookkeeping"], "source_note": "Auto-enriched from repository evidence and institution rules.", "source_type": "official_course_page", "source_url": "https://cas.ac.ls/course/acca/", "supporting_fee_source_path": "data/real/fees/cas-fee-structure-partial-2024.json", "supporting_source_path": "C:/Users/lepha/Downloads/CAS Lesotho Student-Handbook-Volume-4.pdf"}'::jsonb) on conflict (external_key) do update set institution_id = excluded.institution_id, faculty_id = excluded.faculty_id, code = excluded.code, name = excluded.name, category = excluded.category, qualification_level = excluded.qualification_level, duration_text = excluded.duration_text, delivery_mode = excluded.delivery_mode, overview = excluded.overview, review_status = excluded.review_status, raw_payload = excluded.raw_payload;
insert into public.programme_sources (programme_id, source_document_id, relation_type, extraction_method, evidence_text) values ((select id from public.programmes where external_key = 'centre-for-accounting-studies-association-of-chartered-certified-accountants-acca' limit 1), (select id from public.source_documents where url = 'https://cas.ac.ls/course/acca/' limit 1), 'primary', 'html_course_page_plus_manual_handbook_extract', 'CAT entry requires LGCSE/COSC with minimum 6 subjects, 4 credits including Mathematics or English or Accounting, and aggregate not exceeding 36. Applied Knowledge entry is available to non-accounting degree holders, diploma holders from HEI/TVET, or A-Level applicants with Mathematics and English plus 3 years accounting work experience.') on conflict (programme_id, source_document_id, relation_type) do update set extraction_method = excluded.extraction_method, evidence_text = excluded.evidence_text;
