insert into public.programmes (external_key, institution_id, faculty_id, code, name, category, qualification_level, duration_text, delivery_mode, overview, review_status, raw_payload) values ('centre-for-accounting-studies-chartered-institute-of-management-accountants-cima', (select id from public.institutions where name = 'Centre for Accounting Studies' limit 1), (select f.id from public.faculties f join public.institutions i on i.id = f.institution_id where i.name = 'Centre for Accounting Studies' and f.name = 'Accounting and Financial Services' limit 1), null, 'Chartered Institute of Management Accountants (CIMA)', 'Business & Commerce', 'Professional Qualification', '3 years', null, 'CIMA is the world''s leading, and largest professional body of management accountants. It''s unique blend of management accounting, financial accounting and business oriented subjects produces competent and confident business leaders who can lead their organizations to sustainable success. CIMA is driving the technological evolution in the business world and at the core of the CIMA qualification are digital skills which ensure our students and members remain relevant in driving organizations forward.', 'approved', '{"career_options": ["Accountant", "Auditor", "Financial Analyst", "Banking Officer"], "category": "Business & Commerce", "duration": "3 years", "extraction_method": "html_course_page_plus_manual_handbook_extract", "faculty": "Accounting and Financial Services", "fee_note": "Fee schedule available: CAS fees partial manual extract (current evidence). Confirm the programme group and latest amount before payment.", "handbook_levels": ["Certificate in Business Accounting", "Diploma (Operational)", "Advanced Diploma (Management)", "Chartered Management Accounting"], "id": "centre-for-accounting-studies-chartered-institute-of-management-accountants-cima", "institution": "Centre for Accounting Studies", "level": "Professional Qualification", "name": "Chartered Institute of Management Accountants (CIMA)", "overview": "CIMA is the world''s leading, and largest professional body of management accountants. It''s unique blend of management accounting, financial accounting and business oriented subjects produces competent and confident business leaders who can lead their organizations to sustainable success. CIMA is driving the technological evolution in the business world and at the core of the CIMA qualification are digital skills which ensure our students and members remain relevant in driving organizations forward.", "requirements_summary": "Certificate in Business Accounting entry uses the same LGCSE/COSC requirements as CAT; or a TVET Diploma; or comparable qualifications.", "review_status": "approved", "skill_options": ["Financial reporting", "Auditing", "Taxation", "Bookkeeping"], "source_note": "Auto-enriched from repository evidence and institution rules.", "source_type": "official_course_page", "source_url": "https://cas.ac.ls/course/cima/", "supporting_fee_source_path": "data/real/fees/cas-fee-structure-partial-2024.json", "supporting_source_path": "C:/Users/lepha/Downloads/CAS Lesotho Student-Handbook-Volume-4.pdf"}'::jsonb) on conflict (external_key) do update set institution_id = excluded.institution_id, faculty_id = excluded.faculty_id, code = excluded.code, name = excluded.name, category = excluded.category, qualification_level = excluded.qualification_level, duration_text = excluded.duration_text, delivery_mode = excluded.delivery_mode, overview = excluded.overview, review_status = excluded.review_status, raw_payload = excluded.raw_payload;
