insert into public.programmes (external_key, institution_id, faculty_id, code, name, category, qualification_level, duration_text, delivery_mode, overview, review_status, raw_payload) values ('centre-for-accounting-studies-bachelor-of-arts-in-financial-services-bafs', (select id from public.institutions where name = 'Centre for Accounting Studies' limit 1), (select f.id from public.faculties f join public.institutions i on i.id = f.institution_id where i.name = 'Centre for Accounting Studies' and f.name = 'Accounting and Financial Services' limit 1), null, 'Bachelor of Arts in Financial Services (BAFS)', 'Business & Commerce', 'Degree', '3 years', null, 'Financial services is an area in the business ecosystem associated with management of money, value creation, financial assets and property. A career in the financial services sector is potentially an appealing prospect to those who have keen interest and aptitude to work in the ever-growing sector, characterised by dynamism, digitalisation and constant innovation.', 'approved', '{"career_options": ["Accountant", "Auditor", "Financial Analyst", "Banking Officer"], "category": "Business & Commerce", "duration": "3 years", "extraction_method": "html_course_page", "faculty": "Accounting and Financial Services", "fee_note": "Fee schedule available: CAS fees partial manual extract (current evidence). Confirm the programme group and latest amount before payment.", "handbook_levels": null, "id": "centre-for-accounting-studies-bachelor-of-arts-in-financial-services-bafs", "institution": "Centre for Accounting Studies", "level": "Degree", "name": "Bachelor of Arts in Financial Services (BAFS)", "overview": "Financial services is an area in the business ecosystem associated with management of money, value creation, financial assets and property. A career in the financial services sector is potentially an appealing prospect to those who have keen interest and aptitude to work in the ever-growing sector, characterised by dynamism, digitalisation and constant innovation.", "requirements_summary": "DIRECT ENTRY: LGCSE - A Candidate Should have sat for a minimum of six (6) subjects, Must have four credits which include Mathematics and English Language and any other two (2) subjects, plus Passes in any two (2) subjects Admissions Points Score (APS) should not exceed 34. COSC A candidate. Should have sat for a minimum of six (6) subjects, Must have four credits which include Mathematics and English Language and any other two (2) subjects, plus Passes in any two (2) subjects Admissions Points Score (APS) should not exceed 34. INTERNATIONAL STUDENTS International students who hold foreign qualifications are advised to submit their transcripts or results slips to Examination Council of Lesotho (ECOL) for evaluation and conversion of their results to the local standards so that CAS can assess them accordingly. INDIRECT ENTRY: A candidate should have A pass or better in Diploma in Business Management or equivalent qualifications from recognised institutions or, IB Diploma with a minimum of six subjects, including three at higher level, and should have achieved a total score of at least 30 out of 45 points or,", "review_status": "approved", "skill_options": ["Financial reporting", "Auditing", "Taxation", "Bookkeeping"], "source_note": "Auto-enriched from repository evidence and institution rules.", "source_type": "official_course_page", "source_url": "https://cas.ac.ls/bachelor-of-arts-in-financial-services-bafs/", "supporting_fee_source_path": "data/real/fees/cas-fee-structure-partial-2024.json", "supporting_source_path": null}'::jsonb) on conflict (external_key) do update set institution_id = excluded.institution_id, faculty_id = excluded.faculty_id, code = excluded.code, name = excluded.name, category = excluded.category, qualification_level = excluded.qualification_level, duration_text = excluded.duration_text, delivery_mode = excluded.delivery_mode, overview = excluded.overview, review_status = 