insert into public.programme_sources (programme_id, source_document_id, relation_type, extraction_method, evidence_text) values ((select id from public.programmes where external_key = 'centre-for-accounting-studies-bachelor-of-arts-in-financial-services-bafs' limit 1), (select id from public.source_documents where url = 'https://cas.ac.ls/bachelor-of-arts-in-financial-services-bafs/' limit 1), 'primary', 'html_course_page', 'DIRECT ENTRY: LGCSE - A Candidate Should have sat for a minimum of six (6) subjects, Must have four credits which include Mathematics and English Language and any other two (2) subjects, plus Passes in any two (2) subjects Admissions Points Score (APS) should not exceed 34. COSC A candidate. Should have sat for a minimum of six (6) subjects, Must have four credits which include Mathematics and English Language and any other two (2) subjects, plus Passes in any two (2) subjects Admissions Points Score (APS) should not exceed 34. INTERNATIONAL STUDENTS International students who hold foreign qualifications are advised to submit their transcripts or results slips to Examination Council of Lesotho (ECOL) for evaluation and conversion of their results to the local standards so that CAS can assess them accordingly. INDIRECT ENTRY: A candidate should have A pass or better in Diploma in Business Management or equivalent qualifications from recognised institutions or, IB Diploma with a minimum of six subjects, including three at higher level, and should have achieved a total score of at least 30 out of 45 points or,') on conflict (programme_id, source_document_id, relation_type) do update set extraction_method = excluded.extraction_method, evidence_text = excluded.evidence_text;
